"""Estilos CSS de la interfaz de Dominó Rural."""

CSS = "body {\n  font-family: system-ui, sans-serif;\n  background: #0f1115;\n  color: #e6e6e6;\n  max-width: 850px;\n  margin: 40px auto;\n  padding: 0 20px;\n}\n\nh1 {\n  font-size: 1.3rem;\n  letter-spacing: 0.5px;\n  text-transform: uppercase;\n  color: #ccc;\n  border-bottom: 2px solid #c0392b;\n  padding-bottom: 10px;\n}\n\n#subtitulo {\n  color: #999;\n  font-size: 0.9rem;\n  margin: 6px 0 20px 0;\n}\n\n#leyenda {\n  display: flex;\n  gap: 20px;\n  margin-bottom: 16px;\n  font-size: 0.85rem;\n  color: #ccc;\n}\n#leyenda .item { display: flex; align-items: center; gap: 6px; }\n.punto {\n  width: 10px;\n  height: 10px;\n  border-radius: 50%;\n  display: inline-block;\n}\n.punto.verde { background: #2ecc71; }\n.punto.rojo { background: #c0392b; }\n.punto.gris { background: #555; }\n\nlabel {\n  display: block;\n  font-size: 0.85rem;\n  color: #999;\n  margin-bottom: 6px;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\nselect, button {\n  font-size: 1rem;\n  padding: 8px 12px;\n  margin-right: 8px;\n  border-radius: 6px;\n  border: 1px solid #444;\n  background: #1a1d24;\n  color: #e6e6e6;\n}\nbutton { cursor: pointer; background: #c0392b; border: none; }\nbutton:hover { background: #e74c3c; }\n#btnReset { background: #555; }\n\nsvg { margin-top: 24px; background: #15161a; border-radius: 8px; }\n\n.linea { stroke: #2ecc71; stroke-width: 4; transition: all 0.3s ease; }\n.linea.cortada { stroke: #c0392b; stroke-dasharray: 8 6; }\n\n.nodo-circulo { fill: #1a1d24; stroke: #2ecc71; stroke-width: 3; transition: all 0.4s ease; }\n.nodo-circulo.zona-segura { stroke: #3498db; }\n.nodo-circulo.apagado { fill: #0f1115; stroke: #444; opacity: 0.3; }\n\n.nodo-texto { fill: #e6e6e6; font-size: 12px; font-weight: bold; text-anchor: middle; }\n.nodo-dato { fill: #aaa; font-size: 9px; text-anchor: middle; }\n.nodo-grupo.apagado .nodo-texto,\n.nodo-grupo.apagado .nodo-dato { opacity: 0.3; }\n\n#resumen {\n  margin-top: 16px;\n  padding: 14px;\n  background: #1a1d24;\n  border-radius: 6px;\n  border-left: 4px solid #f1c40f;\n  font-size: 0.95rem;\n  line-height: 1.6;\n  display: none;\n}\n#resumen b { color: #f1c40f; }"
